def nfc(o):
    if isinstance(o, str): return unicodedata.normalize("NFC", o)
    if isinstance(o, list): return [nfc(x) for x in o]
    if isinstance(o, dict): return {k: nfc(v) for k, v in o.items()}
    return o

out = os.path.join(HERE, "doc_luzhniki-stadium.json")
json.dump(nfc(doc), open(out, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
wc = sum(len(p.split()) for s in doc["sections"] for p in s["paras"])
print("WROTE", out, "| sections:", len(doc["sections"]), "| ~words:", wc,
      "| images:", len(doc["images"]), "| refs:", len(doc["references"]))
